<template>
  <div class="runner-dashboard">
    <router-link v-if="nextRace" class="next-race dash-card" :to="'/races/' + nextRace.race.id"><span class="next-date"><span>{{ nextRace.race.raceDate.slice(5, 7) }} 月</span><b>{{ nextRace.race.raceDate.slice(8, 10) }}</b></span><div><span class="overline">下一场赛事 · {{ nextRace.status }}</span><h3>{{ nextRace.race.name }}</h3><p>{{ nextRace.race.city || '比赛地点待公布' }} · {{ nextRace.race.raceDate }}</p></div><RunnerIcon name="arrow"/></router-link>
    <section v-if="error" class="dash-card dash-error" role="alert"><p>运动摘要暂时没有加载出来</p><button type="button" @click="$emit('retry')">重新加载</button></section>
    <section v-else class="dash-card week-card" :aria-busy="loading">
      <div class="dash-heading"><h3>本周运动</h3><router-link to="/runner?view=stats" aria-label="查看运动数据">数据详情 <span>›</span></router-link></div>
      <div class="week-main"><div><div class="week-number">{{ loading ? '—' : number(overview.weekKm) }}<small>公里</small></div><p>{{ loading ? '正在整理记录' : `${overview.weekCount || 0} 次运动 · ${minutes(overview.weekDurationSec)} 分钟` }}</p></div><div class="mini-chart" aria-label="本周每日跑量"><div v-for="(bar, i) in bars" :key="bar.key || i" class="mini-day"><div class="mini-track"><i :class="{ today: bar.key === data?.asOf, zero: !bar.km }" :style="{ height: `${bar.km ? Math.max(8, bar.km / maxKm * 100) : 5}%` }"></i></div><span>{{ ['一','二','三','四','五','六','日'][i] }}</span></div></div></div>
      <router-link class="week-foot" to="/runner?view=stats&report=1"><span>跑量 · 时长 · 配速</span><b>运动周报 <span>›</span></b></router-link>
    </section>
    <section class="dash-card career-card"><div class="dash-heading"><h3 class="career-heading">个人最好成绩</h3><router-link to="/runner?view=career">赛事生涯 <span>›</span></router-link></div><div class="pb-grid"><router-link v-for="item in pbs" :key="item.distance" to="/runner?view=career"><span>{{ item.label }}</span><b :class="{ 'awaiting-pb': !item.clock }">{{ item.clock || '暂无成绩' }}</b><small>{{ item.clock ? 'PB · 个人最佳' : '添加一场完赛记录' }}</small></router-link></div><slot name="career-actions" /></section>
    <section class="archive-workbench"><div class="dash-heading archive-heading"><h3>我的跑者服务</h3></div><nav class="dash-entries" aria-label="跑者档案"><router-link v-for="entry in entries" :key="entry.id" :to="entry.to || '/runner?view=' + entry.id"><span class="entry-icon" :class="entry.id"><RunnerIcon :name="entry.id === 'history' ? 'career' : entry.id"/></span><div><b>{{ entry.title }}</b></div></router-link></nav></section>
    <p class="private-note"><RunnerIcon name="lock"/>个人运动、收藏与影像，仅自己可见</p>
  </div>
</template>
<script setup>
import { computed } from 'vue';
import RunnerIcon from './RunnerIcon.vue';
const props = defineProps({ data: Object, plans: { type: Array, default: () => [] }, loading: Boolean, error: String });
defineEmits(['retry']);
const overview = computed(() => props.data?.overview || {});
const bars = computed(() => props.data?.training?.bars?.slice(0, 7) || Array.from({ length: 7 }, (_, i) => ({ key: i, km: 0 })));
const maxKm = computed(() => Math.max(1, ...bars.value.map(x => x.km)));
const nextRace = computed(() => props.plans.filter(x => x.race?.raceDate >= (props.data?.asOf || new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Shanghai' })) && !['未中签','弃赛','未完赛','完赛'].includes(x.status)).sort((a,b) => a.race.raceDate.localeCompare(b.race.raceDate))[0]);
const pbs = computed(() => [{distance:'full',label:'全马最好成绩'},{distance:'half',label:'半马最好成绩'}].map(x => ({...x,clock:props.data?.career?.pb?.find(p => p.distance === x.distance)?.clock})));
const entries = [ {id:'stats',title:'运动数据',subtitle:'跑量与趋势'}, {id:'career',title:'赛事生涯',subtitle:'成绩与 PB'}, {id:'footprints',title:'城市足迹',subtitle:'我的城市护照'}, {id:'honors',title:'荣誉收藏',subtitle:'证书与奖牌'}, {id:'media',title:'赛事影像',subtitle:'留住高光时刻'}, {id:'devices',title:'数据来源',subtitle:'导入与设备'}, {id:'history',title:'我的跑史',subtitle:'历史成绩',to:'/history'}, {id:'help',title:'使用帮助',subtitle:'记录与导入'} ];
function number(value) { return Number(value || 0).toLocaleString('zh-CN',{maximumFractionDigits:2}); }
function minutes(value) { return Math.round(Number(value || 0) / 60); }
</script>
